use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let arr1 = input.as_array().unwrap();
    let arr2 = input.as_array().unwrap();
    let n1 = arr1.len() as i64;
    let n2 = arr2.len() as i64;
    let mut result = Vec::new();
    let mut i = 0;
    let mut j = 0;
    while i < n1 && j < n2 {
        if arr1[i].as_i64().unwrap() < arr2[j].as_i64().unwrap() {
            result.push(Some(arr1[i].as_i64().unwrap()));
            i += 1;
        } else {
            result.push(None);
            j += 1;
        }
    }
    Value::Array(result.into_iter().map(|v| v.unwrap()).collect())
}
